import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.CWYzGJW1.js";const b=JSON.parse('{"title":"使用說明與學習路線","description":"這本手冊整理如何在自己的電腦或機房裡架設 AI. 整份手冊以一張架構圖為終點, 分四部逐步走到那裡.","frontmatter":{"description":"這本手冊整理如何在自己的電腦或機房裡架設 AI. 整份手冊以一張架構圖為終點, 分四部逐步走到那裡."},"headers":[],"relativePath":"index.md","filePath":"start/usage.md","lastUpdated":1793035092000}'),o={name:"index.md"};function i(l,t,n,h,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="使用說明與學習路線" tabindex="-1">使用說明與學習路線 <a class="header-anchor" href="#使用說明與學習路線" aria-label="Permalink to &quot;使用說明與學習路線&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-27</li><li>待查證: 硬體自我檢測的查詢指令未實機驗證; 硬體等級 A 至 F 為整理者設計的分級 (定義見 K3.1 節), 非業界標準; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 這本手冊整理如何在自己的電腦或機房裡架設 AI. 整份手冊以一張<a href="/lanai-handbook/start/map">架構圖</a>為終點, 分四部逐步走到那裡: 第一部講懂每個元件背後的原理, 第二部一次組裝一個模組, 第三部用範例說明組好的系統能解決什麼問題, 第四部是長期維運. 先回答三個問題, 選一條學習路線, 再依路線閱讀即可, 不必從頭讀到尾.</p><p>手冊不預設地端優於雲端, 也不包含法規解讀; 涉及法規的決定, 請洽法律顧問.</p><h2 id="地端是什麼" tabindex="-1">地端是什麼 <a class="header-anchor" href="#地端是什麼" aria-label="Permalink to &quot;地端是什麼&quot;">​</a></h2><p>日常使用的 ChatGPT 之類的 AI 服務, 是跑在別人的資料中心裡 (雲端), 輸入的內容會送到對方的機器上. 「地端」指的是反過來: 把 AI 放在自己擁有的電腦或機房裡運轉, 輸入的資料只在自己的網路內流動.</p><p>自己架設, 好處是資料可以留在內部, 代價是硬體, 電費與維護都要自己負責. 多數人需要的不是「裝完就好」, 而是看得懂每一塊在做什麼, 才有辦法判斷哪裡出了問題, 以及哪些風險要先處理. 所以手冊除了步驟之外, 也說明各元件背後的原理與取捨.</p><h2 id="手冊結構" tabindex="-1">手冊結構 <a class="header-anchor" href="#手冊結構" aria-label="Permalink to &quot;手冊結構&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部</th><th>內容</th><th>讀完能做到</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/start/map">架構地圖</a></td><td>最終要組出的系統, 以及每一塊由哪個模組組裝</td><td>知道自己需要哪幾塊</td></tr><tr><td>第一部 底層知識 (K1 至 K6)</td><td>模型, 量化 (把模型檔壓小), 硬體, 授權, 工具呼叫, 安全</td><td>看懂圖上每個方塊在做什麼, 為什麼要這樣分區</td></tr><tr><td>第二部 模組化組裝 (M0 至 M9)</td><td>由下往上, 每章組裝一個模組, 附驗收測試</td><td>一步一步把系統架起來</td></tr><tr><td>第三部 應用範例 (P1 至 P3, E1 至 E5)</td><td>個人與企業的常見用途</td><td>知道組好的系統怎麼用在日常工作</td></tr><tr><td>第四部 維運 (O1 至 O3)</td><td>備份, 版本鎖定, 安全公告</td><td>讓系統長期安全運作</td></tr></tbody></table><p>另有<a href="/lanai-handbook/decide/summary">決策參考</a> (該不該自架, 成本, 風險) 與延伸主題<a href="/lanai-handbook/train/t1-decide">訓練微調</a>. 遇到不熟的詞, 可查<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p><h2 id="先回答三個問題" tabindex="-1">先回答三個問題 <a class="header-anchor" href="#先回答三個問題" aria-label="Permalink to &quot;先回答三個問題&quot;">​</a></h2><p>這三個問題決定該從哪裡開始, 以及系統做到多大才合適. 做太大, 會變成沒有人顧得了的負擔; 做太小, 又不夠用.</p><table tabindex="0"><thead><tr><th>問題</th><th>選項</th></tr></thead><tbody><tr><td>1. 想做什麼</td><td>a. 自己用 / b. 給 2 人以上共用 / c. 還在評估該不該自架 / d. 想訓練或微調 (在現成模型上再教它一些東西)</td></tr><tr><td>2. 手上是什麼硬體</td><td>見下方「硬體自我檢測」, 對應等級 A 至 F</td></tr><tr><td>3. 之後誰維運</td><td>有人每週檢查安全公告與備份 / 沒有固定的人</td></tr></tbody></table><p>「維運」指系統上線之後的持續照顧: 定期備份資料, 更新軟體, 留意有沒有新發現的安全漏洞. 第 3 題的答案會限制能組到哪裡: 沒有人固定維運時, 只組到里程碑 1 (M0 至 M2). 里程碑是手冊切出的三個階段, 每個階段完成後都是一套可以獨立使用的系統, 不必一次做完. 這個限制的理由是: 越複雜的系統越需要有人定期照顧 (整理者建議, 推論, 信心: 中; 理由見<a href="/lanai-handbook/build/overview">組裝總覽</a>與 <a href="/lanai-handbook/ops/advisories">O3</a>).</p><h2 id="選一條學習路線" tabindex="-1">選一條學習路線 <a class="header-anchor" href="#選一條學習路線" aria-label="Permalink to &quot;選一條學習路線&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路線</th><th>閱讀順序</th><th>終點</th></tr></thead><tbody><tr><td>a. 個人路線</td><td>架構地圖 → K1, K2, K3 → M0 (單機做法) → M1 → M2 → 需要問文件時加 M4 → 範例 P1 至 P3 → O1, O2</td><td>里程碑 1, 視需要加檢索</td></tr><tr><td>b. 企業路線</td><td>架構地圖 → K1 至 K6 → M0 至 M4 與 M6 (里程碑 2; M5 符合 M5.1 節的條件才加) → 有人每週維運時再加 M7 至 M9 (里程碑 3) → 範例 E1 至 E5 → O1 至 O3</td><td>里程碑 2 或 3</td></tr><tr><td>c. 決策者路線</td><td>決策參考整組頁面 → 架構地圖</td><td>判斷要不要投入, 投入到哪個里程碑</td></tr><tr><td>d. 訓練或微調</td><td>T1 (先判斷是否需要) → T2</td><td>多數需求用提示與檢索即可, 見 T1</td></tr></tbody></table><p>每個模組章都依同一個格式撰寫: 這一塊在圖上的位置, 前置模組, 安裝步驟, 驗收測試, 完成後的狀態. 組完一章再進下一章, 遇到問題時比較容易找出是哪一塊出錯. 「驗收測試」是每章最後的檢查清單, 全部通過才算這一塊組好了.</p><h2 id="硬體自我檢測" tabindex="-1">硬體自我檢測 <a class="header-anchor" href="#硬體自我檢測" aria-label="Permalink to &quot;硬體自我檢測&quot;">​</a></h2><p>AI 模型要先整個放進記憶體才能運轉, 所以決定電腦「跑不跑得動」的, 主要是記憶體容量, 不是 CPU 有多快. 有獨立顯示卡的電腦, 模型通常放在顯示卡自己的記憶體 (稱為顯示記憶體), 容量通常比一般記憶體小得多. Apple Silicon 的 Mac 則不同, 處理器與顯示晶片共用同一塊記憶體 (稱為統一記憶體), 所以整台 Mac 的記憶體容量就是上限. 因此只需要查出三個資訊: 顯示卡型號與顯示記憶體容量, 系統記憶體容量, 以及 Mac 的晶片是不是 Apple Silicon.</p><h3 id="查出自己的規格" tabindex="-1">查出自己的規格 <a class="header-anchor" href="#查出自己的規格" aria-label="Permalink to &quot;查出自己的規格&quot;">​</a></h3><p>指令是在「終端機」這類可以輸入文字指令的視窗裡執行. Windows 與 Mac 都內建這類視窗, 名稱和開啟方式依系統版本而異, 請以系統說明為準. 輸出會附單位, 讀數字時請留意單位, 只要找出上面三個資訊即可.</p><p>以下指令未實機驗證, 輸出欄位名稱會因作業系統版本而異; 若與說明不符, 以系統設定畫面為準.</p><table tabindex="0"><thead><tr><th>系統</th><th>指令</th><th>看什麼</th></tr></thead><tbody><tr><td>Windows 或 Linux, 有 NVIDIA 顯示卡</td><td><code>nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv</code></td><td>顯示卡型號, 顯示記憶體, 驅動版本 (驅動程式的版本號)</td></tr><tr><td>macOS</td><td><code>system_profiler SPHardwareDataType</code></td><td>晶片 (是否為 Apple Silicon) 與記憶體</td></tr><tr><td>Linux</td><td><code>free -h</code></td><td>系統記憶體</td></tr><tr><td>Windows (PowerShell)</td><td><code>Get-CimInstance Win32_ComputerSystem | Select-Object TotalPhysicalMemory</code></td><td>系統記憶體 (單位為位元組)</td></tr></tbody></table><h3 id="對應等級" tabindex="-1">對應等級 <a class="header-anchor" href="#對應等級" aria-label="Permalink to &quot;對應等級&quot;">​</a></h3><p>查出規格後, 對照下表找到自己的等級. 等級只是粗略的起點建議, 不是上限.</p><table tabindex="0"><thead><tr><th>等級</th><th>特徵</th><th>建議起點</th></tr></thead><tbody><tr><td>A</td><td>無獨立顯示卡的筆電</td><td>里程碑 1, 桌面版介面 (見組裝總覽的硬體對應)</td></tr><tr><td>B</td><td>8 至 12GB 顯示記憶體</td><td>8GB 組到里程碑 1; 12GB 以上可組到里程碑 2</td></tr><tr><td>C</td><td>Apple Silicon Mac, 以統一記憶體容量決定能力</td><td>16GB 組到里程碑 1; 32GB 以上可組到里程碑 2</td></tr><tr><td>D</td><td>16GB 顯示記憶體</td><td>里程碑 2</td></tr><tr><td>E</td><td>24GB 以上, 未滿 48GB 顯示記憶體</td><td>里程碑 2</td></tr><tr><td>F</td><td>48GB 以上顯示記憶體, 或多卡</td><td>里程碑 3 (須有人每週維運)</td></tr></tbody></table><p>顯示記憶體 (或統一記憶體) 比運算速度更常決定「模型跑不跑得起來」, 估算方法見 K2. A 至 F 是整理者依記憶體容量設計的分級, 不是業界標準; 各等級的定義與可跑的模型大小見 <a href="/lanai-handbook/know/k3-hardware">K3</a> 的 K3.1 節 (推論, 信心: 中). 想先知道買什麼設備, 預算多少, 見 <a href="/lanai-handbook/know/k3-hardware">K3 硬體</a>與<a href="/lanai-handbook/ref/hardware-prices">硬體價格頁</a>.</p><h2 id="決策者-先看這幾頁" tabindex="-1">決策者: 先看這幾頁 <a class="header-anchor" href="#決策者-先看這幾頁" aria-label="Permalink to &quot;決策者: 先看這幾頁&quot;">​</a></h2><p>不需要先懂技術, 也能判斷該不該自架. 建議順序如下:</p><ol><li><a href="/lanai-handbook/decide/summary">一頁決策摘要</a>: 三分鐘看完結論與前提.</li><li><a href="/lanai-handbook/decide/should-self-host">該不該自架決策樹</a>: 依資料敏感度, 使用人數與維運能力判斷.</li><li><a href="/lanai-handbook/decide/tco">成本試算表</a>: 自己填入數字, 比較自架與雲端 API.</li><li><a href="/lanai-handbook/decide/risk-checklist">風險自評</a>: 十個問題, 看維運前提是否成立.</li><li><a href="/lanai-handbook/decide/license-flags">授權紅旗</a>: 對外提供服務前, 哪些授權條款要先處理.</li><li><a href="/lanai-handbook/decide/poc-30days">30 天 PoC 計畫</a>: 用最小代價驗證 (PoC 即概念驗證, 先做一個小規模試用), 再決定是否投入.</li></ol><h2 id="標示的讀法" tabindex="-1">標示的讀法 <a class="header-anchor" href="#標示的讀法" aria-label="Permalink to &quot;標示的讀法&quot;">​</a></h2><p>每章開頭的屬性框與正文中的標記, 用來快速判斷這一段可以信到什麼程度.</p><table tabindex="0"><thead><tr><th>標示</th><th>意義</th></tr></thead><tbody><tr><td>● 必要</td><td>所有讀者都需要</td></tr><tr><td>○ 依情境</td><td>符合條件才讀, 條件寫在章首</td></tr><tr><td>◇ 進階或選讀</td><td>初階讀者可以略過</td></tr><tr><td>撰寫中 (僅有大綱)</td><td>只有章節骨架, 尚無可用內容</td></tr><tr><td>可閱讀 (部分資料待核對)</td><td>內容可參考, 但標示「待核對」的數字或來源尚未以第一手資料確認</td></tr><tr><td>已審閱</td><td>內容與來源經人工逐項核對</td></tr><tr><td>未實機驗證</td><td>指令依官方文件整理, 尚未在實機執行; 執行前請先在測試環境試跑</td></tr><tr><td>信心: 高 / 中 / 低</td><td>超出事實的判斷所附的信心水準; 標「推論」者為整理者推論</td></tr></tbody></table><p>正文只寫原則與判斷流程. 版本號, CVE (已公開的資安漏洞編號), 價格與基準分數一律放在<a href="/lanai-handbook/ref/versions">參考資料</a>, 並標示來源與資料基準日.</p><h2 id="各章完成度" tabindex="-1">各章完成度 <a class="header-anchor" href="#各章完成度" aria-label="Permalink to &quot;各章完成度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>範圍</th><th>狀態</th></tr></thead><tbody><tr><td>使用說明, 架構地圖, 組裝總覽</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>K1 至 K6</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>M0 至 M3, M7 至 M9</td><td>可閱讀 (指令未實機驗證)</td></tr><tr><td>M4 至 M6</td><td>可閱讀 (部分資料待核對, 指令未實機驗證)</td></tr><tr><td>應用範例</td><td>可閱讀 (部分資料待核對, 未實機驗證)</td></tr><tr><td>O1, O2</td><td>可閱讀 (指令未實機驗證)</td></tr><tr><td>O3</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>T1 至 T3</td><td>可閱讀 (部分資料待核對, 指令未實機驗證)</td></tr><tr><td>參考資料 (術語, 授權, 版本, 硬體價格, 模型建議, 基準分數)</td><td>可閱讀 (部分資料待核對; 基準分數的實測待實機驗證)</td></tr><tr><td>決策參考</td><td>可閱讀 (數字為試算框架, 非市場資料)</td></tr></tbody></table><p>手冊中的指令與設定範例都依官方文件整理, 尚未在實機執行. 各頁「待查證」欄列出尚未查證的事項.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>本頁的手冊結構, 學習路線, 三個問題, 等級對應與完成度表是整理者的設計, 事實依據在各章; 等級 A 至 F 為整理者依記憶體容量設計的分級, 定義與依據見 K3. 頁內查詢指令的出處如下, 指令均未實機驗證.</p><ul><li><strong><code>nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv</code></strong>: NVIDIA 官方文件說明 <code>--query-gpu</code> 接受以逗號分隔的屬性清單, <code>--format=csv</code> 輸出 CSV. 該頁未列出 <code>name</code>, <code>memory.total</code>, <code>driver_version</code> 三個屬性名稱, 並指向 <code>--help-query-gpu</code> 查詢可用屬性, 因此使用前請先在自己的機器上執行 <code>nvidia-smi --help-query-gpu</code> 核對. <a href="https://docs.nvidia.com/deploy/nvidia-smi/index.html" target="_blank" rel="noreferrer">NVIDIA: nvidia-smi 文件</a></li><li><strong><code>system_profiler SPHardwareDataType</code></strong>: 指令說明取自 Apple man page 的網路鏡像 (二手來源), 其中 <code>-listDataTypes</code> 可列出可用的資料類型; 資料類型名稱 <code>SPHardwareDataType</code> 取自第三方指令參考站 (二手來源), 請以 <code>system_profiler -listDataTypes</code> 的輸出核對. <a href="https://keith.github.io/xcode-man-pages/system_profiler.8.html" target="_blank" rel="noreferrer">system_profiler(8) man page (鏡像)</a>, <a href="https://ss64.com/mac/system_profiler.html" target="_blank" rel="noreferrer">ss64: system_profiler</a></li><li><strong><code>free -h</code></strong>: man page 說明 <code>-h</code> (<code>--human</code>) 以易讀的單位顯示記憶體量. <a href="https://man7.org/linux/man-pages/man1/free.1.html" target="_blank" rel="noreferrer">free(1) man page</a></li><li><strong><code>Get-CimInstance Win32_ComputerSystem</code> 的 <code>TotalPhysicalMemory</code></strong>: Microsoft 文件說明單位為位元組; 同頁提醒在某些情況下 (例如 BIOS 保留一部分記憶體) 此值不準確, 精確值應改用 <code>Win32_PhysicalMemory</code> 的 <code>Capacity</code>. <a href="https://learn.microsoft.com/en-us/windows/win32/cimwin32prov/win32-computersystem" target="_blank" rel="noreferrer">Microsoft: Win32_ComputerSystem class</a></li><li><strong>Apple Silicon 採統一記憶體</strong>: Apple 2020-11 發表 M1 的新聞稿寫明採 unified memory architecture; 各代晶片的記憶體上限與頻寬不在本頁討論範圍. <a href="https://www.apple.com/newsroom/2020/11/apple-unleashes-m1/" target="_blank" rel="noreferrer">Apple Newsroom: Apple unleashes M1</a></li><li><strong>「顯示記憶體比運算速度更常決定模型跑不跑得起來」</strong>: 依據是 <a href="/lanai-handbook/know/k2-quantization">K2</a> 的估算算式與 <a href="/lanai-handbook/know/k3-hardware">K3</a>, 屬算術與整理者判斷 (信心: 高).</li><li><strong>「沒有人固定維運時只組到里程碑 1」</strong>: 整理者建議 (推論, 信心: 中), 理由見<a href="/lanai-handbook/build/overview">組裝總覽</a>與 <a href="/lanai-handbook/ops/advisories">O3</a>.</li><li><strong>文中的類比與說明</strong>: 整理者所寫, 無外部來源, 不應當作技術定義引用. 其中「模型要先整個放進記憶體才能運轉」依據 K2 的估算算式; 「Windows 與 Mac 都內建終端機類視窗」為一般常識, 開啟方式未查證.</li></ul>',40)])])}const m=a(o,[["render",i]]);export{b as __pageData,m as default};
